// Resolve only authored glyph dictionaries; calling again preserves hydrated objects.
export function resolveFighterGlyphs(fighter) {
  function resolve(dictionary) {
    for (const key of Object.keys(dictionary ?? {})) {
      const reference = dictionary[key];
      if (typeof reference === 'number') {
        const matrix = OPPONENT_GLYPHS[reference];
        if (!matrix) throw Error('Missing opponent ASCII matrix ' + reference);
        dictionary[key] = matrix;
      }
    }
  }
  resolve(fighter.glyphs);
  resolve(fighter.alternateGlyphs);
  for (const field of ['bankGlyphs', 'alternateBankGlyphs']) {
    for (const dictionary of Object.values(fighter[field] ?? {})) resolve(dictionary);
  }
  return fighter;
}
